var biostationtimechange={init:function(){biostationtimechange.handleFilter();biostationtimechange.loadDefault()},loadDefault:function(){$(".form-filter").trigger("submit")},handleFilter:function(){var n=$(".form-filter");$(n).on("submit",function(t){t.preventDefault();$.ajax({url:n.attr("action"),method:n.attr("method"),data:n.serialize(),beforeSend:function(){$(".loading-process").fadeIn(300)},success:function(n){$("#table-list").html(n);floatThead("table#data")},complete:function(){$(".loading-process").fadeOut(300)}})})}};$(document).ready(function(){biostationtimechange.init()});